        text: card.innerText,
        name: card.querySelector('h3, [data-qa-target="provider-name"], [class*="provider-name"]')?.textContent?.trim(),
        specialty: card.querySelector('[data-qa-target="provider-specialty"], [class*="specialty"]')?.textContent?.trim(),
