    headings.forEach(h => {
      const container = h.closest('article, li, div[class*="card"], div[class*="result"]');
      results.push({
        heading: h.textContent.trim(),
        containerText: container ? container.innerText.slice(0, 300) : null
      });
    });
  }
  return results;
});

